from typing import Any, Generator, Optional, Type, cast

from sqlalchemy import Engine
from sqlalchemy.exc import NoResultFound
from sqlmodel import create_engine, SQLModel, Session, select

from feedback_api.core.config import get_config


class DatabaseManager:
    """Manages database engine and session creation."""

    _engine = None

    @classmethod
    def init_engine(cls, postgres_url: Optional[str] = None) -> None:
        """Initialize the database engine with the provided PostgreSQL URL."""
        if postgres_url is None:
            postgres_url = cast(str, get_config().postgres_url)
        cls._engine = create_engine(postgres_url)

    @classmethod
    def get_engine(cls) -> Optional[Engine]:
        """Get the database engine."""
        if cls._engine is None:
            cls.init_engine()
        return cls._engine


def get_db_session() -> Generator[Session, None, None]:
    """Dependency to get DB session"""
    db = Session(DatabaseManager.get_engine())
    try:
        yield db
    finally:
        db.close()


